using System.Collections.Generic;

namespace Sessions.Core;

// Outcome of restoring a single entry.
public sealed record RestoreResult(Entry Entry, bool Success, string? ErrorMessage);

// Restores a session's entries one at a time, continuing past failures and
// reporting the outcome of each.
public sealed class RestoreRunner
{
    private readonly AdapterRegistry _registry;

    public RestoreRunner(AdapterRegistry registry)
    {
        _registry = registry ?? throw new ArgumentNullException(nameof(registry));
    }

    public IReadOnlyList<RestoreResult> Run(IEnumerable<Entry> entries)
    {
        ArgumentNullException.ThrowIfNull(entries);

        List<RestoreResult> results = new();
        foreach (Entry entry in entries)
        {
            IAdapter? adapter = _registry.SelectForRestore(entry);
            if (adapter is null)
            {
                results.Add(new RestoreResult(entry, false, $"No adapter for '{entry.AdapterId}'."));
                continue;
            }

            try
            {
                adapter.Restore(entry);
                results.Add(new RestoreResult(entry, true, null));
            }
            catch (RestoreException ex)
            {
                results.Add(new RestoreResult(entry, false, ex.Message));
            }
        }

        return results;
    }
}

using System.Collections.Generic;
using System.Linq;

namespace Sessions.Core;

// A window that couldn't be captured, with the reason.
public sealed record CaptureFailure(WindowInfo Window, string Reason);

// The result of capturing a session: the built session plus any per-window failures.
public sealed record SessionCaptureResult(Session Session, IReadOnlyList<CaptureFailure> Failures);

// Builds a Session from the user's selected windows, using the first matching
// adapter per window and collecting (rather than throwing on) per-window failures.
public sealed class SessionCaptureService
{
    private readonly AdapterRegistry _registry;
    private readonly Func<IEnumerable<string>> _existingNames;

    public SessionCaptureService(AdapterRegistry registry, Func<IEnumerable<string>> existingNames)
    {
        _registry = registry ?? throw new ArgumentNullException(nameof(registry));
        _existingNames = existingNames ?? throw new ArgumentNullException(nameof(existingNames));
    }

    public SessionCaptureResult Capture(IEnumerable<WindowInfo> windows, string name)
    {
        ArgumentNullException.ThrowIfNull(windows);
        ValidateName(name);

        List<Entry> entries = new();
        List<CaptureFailure> failures = new();

        foreach (WindowInfo window in windows)
        {
            IAdapter? adapter = _registry.SelectForCapture(window);
            if (adapter is null)
            {
                failures.Add(new CaptureFailure(window, window.UnsupportedReason ?? "No adapter can capture this window."));
                continue;
            }

            try
            {
                entries.Add(adapter.Capture(window));
            }
            catch (CaptureException ex)
            {
                failures.Add(new CaptureFailure(window, ex.Message));
            }
        }

        Session session = new(
            SchemaVersion: Session.CurrentSchemaVersion,
            Id: Guid.NewGuid(),
            Name: name,
            CreatedAt: DateTimeOffset.Now,
            Entries: entries);

        return new SessionCaptureResult(session, failures);
    }

    private void ValidateName(string name)
    {
        if (string.IsNullOrWhiteSpace(name))
        {
            throw new ArgumentException("Session name must not be empty.", nameof(name));
        }

        bool exists = _existingNames().Any(
            existing => string.Equals(existing, name, StringComparison.OrdinalIgnoreCase));
        if (exists)
        {
            throw new ArgumentException($"A session named '{name}' already exists.", nameof(name));
        }
    }
}

using Sessions.Core;

namespace Sessions.Tests;

// A minimal entry tied to a given adapter id, for exercising adapters/runners.
internal sealed record FakeEntry(string DisplayName, string AdapterIdValue)
    : Entry(DisplayName, Placement: null)
{
    public override string AdapterId => AdapterIdValue;
}

// Configurable adapter: records whether it was asked to restore, and can fail.
internal sealed class FakeAdapter : IAdapter
{
    private readonly bool _canHandle;
    private readonly string? _failWith;

    public FakeAdapter(string id, bool canHandle = true, string? failWith = null)
    {
        Id = id;
        _canHandle = canHandle;
        _failWith = failWith;
    }

    public string Id { get; }
    public int RestoreCount { get; private set; }

    public bool CanHandle(WindowInfo window) => _canHandle;

    public Entry Capture(WindowInfo window) => new FakeEntry(window.Title, Id);

    public void Restore(Entry entry)
    {
        RestoreCount++;
        if (_failWith is not null)
        {
            throw new RestoreException(_failWith);
        }
    }
}

using Sessions.Core;

namespace Sessions.Tests;

public class AdapterRegistryTests
{
    [Fact]
    public void Generic_IsAlwaysLast()
    {
        FakeAdapter specific = new("specific");
        FakeAdapter generic = new("generic");

        AdapterRegistry registry = new(new[] { specific }, generic);

        Assert.Equal(2, registry.Adapters.Count);
        Assert.Same(generic, registry.Adapters[^1]);
    }

    [Fact]
    public void SelectForCapture_PrefersSpecific_OverGeneric()
    {
        FakeAdapter specific = new("specific", canHandle: true);
        FakeAdapter generic = new("generic", canHandle: true);
        AdapterRegistry registry = new(new[] { specific }, generic);

        IAdapter? chosen = registry.SelectForCapture(SampleWindow());

        Assert.Same(specific, chosen);
    }

    [Fact]
    public void SelectForCapture_FallsBackToGeneric_WhenSpecificDeclines()
    {
        FakeAdapter specific = new("specific", canHandle: false);
        FakeAdapter generic = new("generic", canHandle: true);
        AdapterRegistry registry = new(new[] { specific }, generic);

        IAdapter? chosen = registry.SelectForCapture(SampleWindow());

        Assert.Same(generic, chosen);
    }

    [Fact]
    public void SelectForRestore_MatchesByAdapterId()
    {
        FakeAdapter specific = new("specific");
        FakeAdapter generic = new("generic");
        AdapterRegistry registry = new(new[] { specific }, generic);

        IAdapter? chosen = registry.SelectForRestore(new FakeEntry("w", "specific"));

        Assert.Same(specific, chosen);
    }

    private static WindowInfo SampleWindow() =>
        new(Handle: 1, Title: "w", ProcessId: 1) { ExePath = @"C:\app.exe" };
}

using Sessions.Core;

namespace Sessions.Tests;

public class GenericAdapterTests
{
    private readonly GenericAdapter _adapter = new(
        waiter: new UnusedWaiter(),
        placer: new UnusedPlacer());

    [Fact]
    public void Capture_BuildsGenericEntry_WithArgsStrippedOfExe()
    {
        WindowInfo window = new(Handle: 1, Title: "Notepad", ProcessId: 10)
        {
            ExePath = @"C:\Windows\notepad.exe",
            CommandLine = "\"C:\\Windows\\notepad.exe\" C:\\notes.txt",
            Placement = new Placement(10, 20, 300, 400, 1),
        };

        GenericEntry entry = Assert.IsType<GenericEntry>(_adapter.Capture(window));

        Assert.Equal("Notepad", entry.DisplayName);
        Assert.Equal(@"C:\Windows\notepad.exe", entry.ExePath);
        Assert.Equal(@"C:\notes.txt", entry.Arguments);
        Assert.Equal(new Placement(10, 20, 300, 400, 1), entry.Placement);
    }

    [Fact]
    public void Capture_NoArguments_YieldsEmptyArgs()
    {
        WindowInfo window = new(Handle: 1, Title: "App", ProcessId: 10)
        {
            ExePath = @"C:\app.exe",
            CommandLine = "\"C:\\app.exe\"",
        };

        GenericEntry entry = Assert.IsType<GenericEntry>(_adapter.Capture(window));

        Assert.Equal(string.Empty, entry.Arguments);
    }

    [Fact]
    public void Capture_MissingExePath_Throws()
    {
        WindowInfo window = new(Handle: 1, Title: "Mystery", ProcessId: 10) { ExePath = null };

        Assert.Throws<CaptureException>(() => _adapter.Capture(window));
    }

    [Fact]
    public void CanHandle_FollowsSupportedState()
    {
        WindowInfo supported = new(Handle: 1, Title: "ok", ProcessId: 1) { ExePath = @"C:\a.exe" };
        WindowInfo unsupported = supported with { UnsupportedReason = "nope" };

        Assert.True(_adapter.CanHandle(supported));
        Assert.False(_adapter.CanHandle(unsupported));
    }

    private sealed class UnusedWaiter : IWindowWaiter
    {
        public nint WaitForNewWindow(string exePath, string displayName) =>
            throw new InvalidOperationException("should not be called in capture tests");
    }

    private sealed class UnusedPlacer : IWindowPlacer
    {
        public void Apply(nint hwnd, Placement placement, bool targetElevated) =>
            throw new InvalidOperationException("should not be called in capture tests");
    }
}

using Sessions.Core;

namespace Sessions.Tests;

public class WindowPlacerTests
{
    // A 1920x1040 work area (taskbar at the bottom).
    private static readonly ScreenRect Work = new(0, 0, 1920, 1040);

    [Fact]
    public void OnScreenRectangle_IsUnchanged()
    {
        Placement p = new(100, 100, 800, 600, 1);

        Placement clamped = WindowPlacer.ClampToWorkArea(p, Work);

        Assert.Equal(p, clamped);
    }

    [Fact]
    public void NegativeOffScreen_SlidesBackToOrigin()
    {
        Placement p = new(-500, -300, 800, 600, 1);

        Placement clamped = WindowPlacer.ClampToWorkArea(p, Work);

        Assert.Equal(0, clamped.X);
        Assert.Equal(0, clamped.Y);
        Assert.Equal(800, clamped.Width);
        Assert.Equal(600, clamped.Height);
    }

    [Fact]
    public void PastRightAndBottom_SlidesToFit()
    {
        Placement p = new(1800, 1000, 800, 600, 1);

        Placement clamped = WindowPlacer.ClampToWorkArea(p, Work);

        Assert.Equal(1920 - 800, clamped.X);
        Assert.Equal(1040 - 600, clamped.Y);
    }

    [Fact]
    public void LargerThanWorkArea_ShrinksAndPins()
    {
        Placement p = new(50, 50, 4000, 3000, 1);

        Placement clamped = WindowPlacer.ClampToWorkArea(p, Work);

        Assert.Equal(0, clamped.X);
        Assert.Equal(0, clamped.Y);
        Assert.Equal(1920, clamped.Width);
        Assert.Equal(1040, clamped.Height);
    }

    [Fact]
    public void ShowCmd_IsPreserved()
    {
        Placement p = new(-10, -10, 100, 100, ShowCmd: 3);

        Placement clamped = WindowPlacer.ClampToWorkArea(p, Work);

        Assert.Equal(3, clamped.ShowCmd);
    }
}

using Sessions.Core;

namespace Sessions.Tests;

public class RestoreRunnerTests
{
    [Fact]
    public void Run_ContinuesPastFailure_AndReportsEach()
    {
        FakeAdapter ok = new("ok");
        FakeAdapter bad = new("bad", failWith: "boom");
        AdapterRegistry registry = new(new IAdapter[] { ok, bad }, new FakeAdapter("generic"));
        RestoreRunner runner = new(registry);

        Entry[] entries =
        {
            new FakeEntry("first", "ok"),
            new FakeEntry("second", "bad"),
            new FakeEntry("third", "ok"),
        };

        var results = runner.Run(entries);

        Assert.Equal(3, results.Count);
        Assert.True(results[0].Success);
        Assert.False(results[1].Success);
        Assert.Equal("boom", results[1].ErrorMessage);
        Assert.True(results[2].Success);

        // The failure didn't stop the third entry from being restored.
        Assert.Equal(2, ok.RestoreCount);
        Assert.Equal(1, bad.RestoreCount);
    }

    [Fact]
    public void Run_UnknownAdapterId_IsReportedAsFailure()
    {
        AdapterRegistry registry = new(Array.Empty<IAdapter>(), new FakeAdapter("generic"));
        RestoreRunner runner = new(registry);

        var results = runner.Run(new[] { new FakeEntry("x", "missing") });

        RestoreResult only = Assert.Single(results);
        Assert.False(only.Success);
        Assert.Contains("missing", only.ErrorMessage);
    }
}

using Sessions.Core;

namespace Sessions.Tests;

public class SessionCaptureServiceTests
{
    private static SessionCaptureService Service(params string[] existingNames)
    {
        AdapterRegistry registry = new(Array.Empty<IAdapter>(), new GenericAdapter(
            waiter: new ThrowingWaiter(),
            placer: new ThrowingPlacer()));
        return new SessionCaptureService(registry, () => existingNames);
    }

    private static WindowInfo Window(string title, string? exePath) =>
        new(Handle: 1, Title: title, ProcessId: 1) { ExePath = exePath };

    [Fact]
    public void Capture_EmptyName_Throws()
    {
        Assert.Throws<ArgumentException>(() =>
            Service().Capture(Array.Empty<WindowInfo>(), "   "));
    }

    [Fact]
    public void Capture_DuplicateName_Throws()
    {
        Assert.Throws<ArgumentException>(() =>
            Service("Work").Capture(Array.Empty<WindowInfo>(), "work")); // case-insensitive
    }

    [Fact]
    public void Capture_OneFailure_DoesNotDropTheOthers()
    {
        WindowInfo good1 = Window("Good1", @"C:\a.exe");
        WindowInfo bad = Window("NoExe", exePath: null); // supported but no exe -> CaptureException
        WindowInfo good2 = Window("Good2", @"C:\b.exe");

        SessionCaptureResult result = Service().Capture(new[] { good1, bad, good2 }, "Session");

        Assert.Equal(2, result.Session.Entries.Count);
        Assert.Contains(result.Session.Entries, e => e.DisplayName == "Good1");
        Assert.Contains(result.Session.Entries, e => e.DisplayName == "Good2");

        CaptureFailure failure = Assert.Single(result.Failures);
        Assert.Equal("NoExe", failure.Window.Title);
    }

    private sealed class ThrowingWaiter : IWindowWaiter
    {
        public nint WaitForNewWindow(string exePath, string displayName) =>
            throw new InvalidOperationException();
    }

    private sealed class ThrowingPlacer : IWindowPlacer
    {
        public void Apply(nint hwnd, Placement placement, bool targetElevated) =>
            throw new InvalidOperationException();
    }
}

